import React, { useState, useEffect, useRef, useCallback } from "react";
import * as api from "./api";
import * as billing from "./billing";
import { gifsEnabled, gifProvider, searchGifs } from "./gifs";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

// ─── CONSTANTS ────────────────────────────────────────────────────────────────
const CATEGORIES = ["Tous","Nature","Gastronomie","Jeux","Sport","Culture","Musique","Voyage","Études","Cinéma","Gaming","Nouveaux amis","Pique-nique"];
const CAT_ICONS  = {Tous:"✨",Nature:"🌿",Gastronomie:"🍴",Jeux:"🎲",Sport:"⚽",Culture:"🎭",Musique:"🎵",Voyage:"✈️",Études:"📚",Cinéma:"🎬",Gaming:"🎮","Nouveaux amis":"👋","Pique-nique":"🧺"};
const AVATAR_COLORS = ["#E8008A","#AAEE00","#7B00C8","#D4AF37","#FF4DC4","#66CC00","#C800A0","#88EE00"];
const LOGO_B64 = "data:image/jpeg;base64,";


// ─── STORAGE HELPERS ─────────────────────────────────────────────────────────
const LS = {
  get: (k, def=null) => { try { const v=localStorage.getItem(k); return v?JSON.parse(v):def; } catch { return def; } },
  set: (k,v) => { try { localStorage.setItem(k,JSON.stringify(v)); } catch {} },
};

// ─── THEME ───────────────────────────────────────────────────────────────────
// Logo colors: hot pink #E8008A, lime green #AAEE00, gold #D4AF37
