// VOICE MESSAGE HOOK + COMPONENTS
// ════════════════════════════════════════════════════════════════════════════════
function useVoiceRecorder() {
  const [recording, setRecording] = useState(false);
  const [seconds, setSeconds] = useState(0);
  const mediaRef = useRef(null);
  const streamRef = useRef(null);
  const chunksRef = useRef([]);
  const timerRef = useRef(null);
  const startedAtRef = useRef(0);
  const mimeRef = useRef(null);

  const releaseMic = () => { streamRef.current?.getTracks().forEach(t => t.stop()); streamRef.current = null; };

  // Démarre l'enregistrement. Renvoie true si le micro est prêt.
  const start = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      // mp4/AAC se lit partout (iPhone compris) ; webm en secours
      const mime = ["audio/mp4", "audio/webm;codecs=opus", "audio/webm"].find(m => window.MediaRecorder?.isTypeSupported?.(m));
      mimeRef.current = mime;
      const mr = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
      chunksRef.current = [];
      mr.ondataavailable = e => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      mr.start();
      mediaRef.current = mr;
      startedAtRef.current = Date.now();
      setSeconds(0); setRecording(true);
      timerRef.current = setInterval(() => setSeconds(Math.floor((Date.now() - startedAtRef.current) / 1000)), 250);
      return true;
    } catch {
      releaseMic();
      alert("Accès au microphone refusé. Autorise le micro pour GrouZ dans les réglages du navigateur, puis réessaie.");
      return false;
    }
  };

  // Arrête et renvoie { blob, url, duration, ms } (ou null s'il n'y avait rien)
  const stopAndGet = () => new Promise(resolve => {
    clearInterval(timerRef.current);
    setRecording(false);
    const mr = mediaRef.current;
    if (!mr || mr.state === "inactive") { releaseMic(); resolve(null); return; }
    mr.onstop = () => {
      releaseMic();
      const ms = Date.now() - startedAtRef.current;
      const blob = new Blob(chunksRef.current, { type: mr.mimeType || mimeRef.current || "audio/webm" });
      mediaRef.current = null;
      resolve({ blob, url: URL.createObjectURL(blob), duration: Math.max(1, Math.round(ms / 1000)), ms });
    };
    mr.stop();
  });

  const cancel = () => {
    clearInterval(timerRef.current);
    setRecording(false);
    const mr = mediaRef.current;
    mediaRef.current = null;
    if (mr && mr.state !== "inactive") { mr.onstop = releaseMic; mr.stop(); } else releaseMic();
  };

  useEffect(() => () => { clearInterval(timerRef.current); releaseMic(); }, []);
  return { recording, seconds, start, stopAndGet, cancel };
}

// Waveform bars (static decorative)
function Waveform({ isMe, playing, color }) {
  const bars = [3,5,8,6,10,7,4,9,5,7,4,6,8,5,3];
  return (
    <div style={{ display:"flex", alignItems:"center", gap:2, height:24 }}>
      {bars.map((h, i) => (
        <div key={i} style={{
          width: 3, height: h * 2, borderRadius: 2,
          background: isMe ? "rgba(255,255,255,0.8)" : color,
          opacity: playing ? 1 : 0.5,
          animation: playing ? `wave ${0.4 + i * 0.05}s ease-in-out infinite alternate` : "none",
        }} />
      ))}
    </div>
  );
}

// Voice message bubble
function VoiceMessageBubble({ msg, isMe, t }) {
  const [url, setUrl] = useState(msg.audioURL || null);
  useEffect(() => { if (!url && msg.audio_path) api.voiceUrl(msg.audio_path).then(setUrl).catch(()=>{}); }, [msg.audio_path]);
  const [playing, setPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [err, setErr] = useState(false);
  const audioRef = useRef(null);
  const fmt = s => `${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;

  const toggle = () => {
    const a = audioRef.current;
    if (!a) return;
    if (a.paused) { setErr(false); a.volume = 1; a.play().then(() => setPlaying(true)).catch(() => setErr(true)); }
    else { a.pause(); setPlaying(false); }
  };

  return (
    <div style={{ background: isMe ? t.accent : t.bg3, borderRadius: isMe?"16px 16px 4px 16px":"16px 16px 16px 4px", padding:"10px 14px", display:"flex", alignItems:"center", gap:10, minWidth:180, border: isMe?"none":`1px solid ${t.border}` }}>
      {url && <audio ref={audioRef} src={url} preload="auto" onError={()=>{ setErr(true); setPlaying(false); }} onEnded={()=>setPlaying(false)} onTimeUpdate={()=>{ if(audioRef.current) setProgress(audioRef.current.currentTime/audioRef.current.duration||0); }} />}
      <button onClick={toggle} style={{ width:34, height:34, borderRadius:"50%", background: isMe?"rgba(255,255,255,0.25)":"rgba(0,0,0,0.1)", border:"none", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, color: isMe?"#fff":t.text, opacity: url ? 1 : 0.5 }}>
        {playing
          ? <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>
          : <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><polygon points="5,3 19,12 5,21"/></svg>
        }
      </button>
      <div style={{ flex:1 }}>
        <Waveform isMe={isMe} playing={playing} color={t.accent} />
        <div style={{ display:"flex", justifyContent:"space-between", marginTop:3 }}>
          <span style={{ fontSize:10, color: isMe?"rgba(255,255,255,0.7)":t.text3, fontFamily:"'DM Mono',monospace" }}>
            {err ? "⚠ Lecture impossible" : `${fmt(Math.round((msg.duration||0) * (playing ? progress : 1)))} / ${fmt(msg.duration||0)}`}
          </span>
        </div>
      </div>
      <span style={{ fontSize:11, color: isMe?"rgba(255,255,255,0.6)":t.text3, fontFamily:"'DM Mono',monospace" }}>🎙</span>
    </div>
  );
}

// Barre de saisie : texte + vocal par appui long
//  • maintenir le micro = enregistrer, relâcher = envoyer
//  • glisser vers la gauche = annuler
//  • glisser vers le haut = verrouiller (mains libres), puis ➤ pour envoyer ou 🗑 pour annuler
function ChatInputBar({ onSend, onVoiceSend, onStatus, onPickFile, onGif, t, placeholder="Écrire…", padH=16, padV=12 }) {
  const [msg, setMsg] = useState("");
  const voice = useVoiceRecorder();
  const [mode, setMode] = useState("idle"); // idle | holding | locked
  const [drag, setDrag] = useState({ x: 0, y: 0 });
  const [hint, setHint] = useState(false);
  const gRef = useRef(null);
  const MIN_MS = 700;
  const [menuOpen, setMenuOpen] = useState(false);
  const fileRef = useRef(null);
  const lastTypingRef = useRef(0);
  // pendant un enregistrement, on rappelle régulièrement l'état à l'autre personne
  useEffect(() => { if (!onStatus || mode === "idle") return; const i = setInterval(() => onStatus("recording"), 30000); return () => clearInterval(i); }, [mode]);
  const fmt = s => `${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;

  const send = () => { if (msg.trim()) { onSend(msg.trim()); setMsg(""); lastTypingRef.current = 0; onStatus && onStatus("idle"); } };
  const reset = () => { setMode("idle"); setDrag({ x: 0, y: 0 }); onStatus && onStatus("idle"); };
  const flashHint = () => { setHint(true); setTimeout(() => setHint(false), 1800); };

  const finish = async () => {
    const r = await voice.stopAndGet();
    reset();
    if (!r) return;
    if (r.ms < MIN_MS) return flashHint();       // appui trop court
    onVoiceSend(r.url, r.duration, r.blob);
  };

  const onDown = (e) => {
    e.preventDefault();
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch {}
    const g = { active: true, x0: e.clientX, y0: e.clientY, locked: false, released: false, ready: false, cancelled: false, abort: false };
    gRef.current = g;
    setMode("holding"); setDrag({ x: 0, y: 0 });
    onStatus && onStatus("recording");
    navigator.vibrate?.(12);
    voice.start().then(ok => {
      if (!ok) { g.active = false; reset(); return; }
      g.ready = true;
      if (g.cancelled || g.abort) { voice.cancel(); return; }
      if (g.released && !g.locked) finish();     // relâché pendant l'autorisation du micro
    });
  };

  const onMove = (e) => {
    const g = gRef.current;
    if (!g || !g.active || g.locked) return;
    const dx = e.clientX - g.x0, dy = e.clientY - g.y0;
    setDrag({ x: Math.min(0, dx), y: Math.min(0, dy) });
    if (dy < -70) { g.locked = true; g.active = false; setMode("locked"); setDrag({ x: 0, y: 0 }); navigator.vibrate?.(20); }
    else if (dx < -90) { g.cancelled = true; g.active = false; if (g.ready) voice.cancel(); reset(); }
  };

  const onUp = () => {
    const g = gRef.current;
    if (!g || !g.active) return;
    g.released = true; g.active = false;
    if (g.ready) finish();
  };

  const onCancelGesture = () => {      // geste interrompu par le système : on n'envoie rien
    const g = gRef.current;
    if (!g || !g.active) return;
    g.cancelled = true; g.active = false;
    if (g.ready) voice.cancel();
    reset();
  };

  const lockedCancel = () => { if (gRef.current) gRef.current.abort = true; voice.cancel(); reset(); };
  const lockedSend = () => { if (gRef.current) gRef.current.abort = !gRef.current.ready; finish(); };

  const holding = mode === "holding", locked = mode === "locked";
  const showSend = mode === "idle" && !!msg.trim();
  const cancelOpacity = 1 - Math.min(1, Math.abs(drag.x) / 90);
  const lockProgress = Math.min(1, Math.abs(drag.y) / 70);
  const strip = { flex: 1, display: "flex", alignItems: "center", gap: 10, background: t.accentBg, border: `1px solid ${t.accent}44`, borderRadius: 12, padding: "11px 14px" };

  return (
    <div style={{ padding: `${padV}px ${padH}px calc(${padV}px + env(safe-area-inset-bottom, 0px))`, borderTop: `1px solid ${t.border}`, background: t.bg2, display: "flex", gap: 10, alignItems: "center", position: "relative", userSelect: "none", WebkitUserSelect: "none" }}>
      {hint && (
        <div style={{ position: "absolute", left: "50%", transform: "translateX(-50%)", bottom: "calc(100% + 8px)", background: t.bg3, border: `1px solid ${t.border}`, color: t.text2, fontFamily: "'DM Mono',monospace", fontSize: 11, padding: "7px 12px", borderRadius: 10, whiteSpace: "nowrap", zIndex: 5 }}>
          Maintiens le micro pour enregistrer
        </div>
      )}
      {holding && (
        <div style={{ position: "absolute", right: padH + 4, bottom: "calc(100% + 10px)", zIndex: 5, display: "flex", flexDirection: "column", alignItems: "center", gap: 2, padding: "8px 9px", borderRadius: 20, background: t.bg3, border: `1px solid ${lockProgress > 0.6 ? t.accent : t.border}`, transform: `scale(${1 + lockProgress * 0.25})`, transition: "transform 0.1s" }}>
          <span style={{ fontSize: 16 }}>🔒</span>
          <span style={{ fontSize: 12, color: t.text3 }}>↑</span>
        </div>
      )}

      {menuOpen && (
        <div style={{ position: "absolute", left: padH, bottom: "calc(100% + 8px)", zIndex: 8, background: t.bg2, border: `1px solid ${t.border}`, borderRadius: 14, overflow: "hidden", boxShadow: "0 10px 30px rgba(0,0,0,0.4)" }}>
          <button onClick={() => fileRef.current?.click()} style={{ display: "block", width: "100%", textAlign: "left", padding: "12px 16px", background: "none", border: "none", color: t.text, fontFamily: "'DM Sans',sans-serif", fontSize: 14, cursor: "pointer" }}>📷 Photo ou vidéo</button>
          {onGif && <button onClick={() => { setMenuOpen(false); onGif(); }} style={{ display: "block", width: "100%", textAlign: "left", padding: "12px 16px", background: "none", border: "none", borderTop: `1px solid ${t.border}`, color: t.text, fontFamily: "'DM Sans',sans-serif", fontSize: 14, cursor: "pointer" }}>🎞 GIF</button>}
        </div>
      )}
      {onPickFile && <input ref={fileRef} type="file" accept="image/*,video/*" style={{ display: "none" }}
        onChange={e => { const f = e.target.files?.[0]; e.target.value = ""; setMenuOpen(false); if (f) onPickFile(f); }} />}
      {mode === "idle" && onPickFile && (
        <button onClick={() => setMenuOpen(o => !o)} aria-label="Joindre un fichier" style={{ width: 44, height: 44, borderRadius: "50%", background: menuOpen ? t.accent : t.bg3, border: `1px solid ${menuOpen ? t.accent : t.border}`, color: menuOpen ? "#fff" : t.text2, cursor: "pointer", fontSize: 22, lineHeight: 1, flexShrink: 0, transform: menuOpen ? "rotate(45deg)" : "none", transition: "transform 0.15s" }}>+</button>
      )}

      {mode === "idle" && (
        <input value={msg} onChange={e => { const v = e.target.value; setMsg(v); if (onStatus) { if (v.trim()) { const now = Date.now(); if (now - lastTypingRef.current > 2500) { lastTypingRef.current = now; onStatus("typing"); } } else { lastTypingRef.current = 0; onStatus("idle"); } } }} onKeyDown={e => e.key === "Enter" && send()} placeholder={placeholder}
          style={{ flex: 1, minWidth: 0, padding: "11px 16px", borderRadius: 12, background: t.input, border: `1px solid ${t.border}`, color: t.text, fontSize: 14, fontFamily: "'DM Mono',monospace", outline: "none" }} />
      )}

      {holding && (
        <div style={strip}>
          <div style={{ width: 10, height: 10, borderRadius: "50%", background: "#E8008A", animation: "pulse 1s ease-in-out infinite", flexShrink: 0 }} />
          <span style={{ color: t.accent, fontFamily: "'DM Mono',monospace", fontSize: 13, fontWeight: 700 }}>{fmt(voice.seconds)}</span>
          <span style={{ marginLeft: "auto", color: t.text3, fontFamily: "'DM Mono',monospace", fontSize: 11, opacity: cancelOpacity, whiteSpace: "nowrap" }}>◀ Glisse pour annuler</span>
        </div>
      )}

      {locked && (
        <>
          <button onClick={lockedCancel} aria-label="Annuler" style={{ width: 44, height: 44, borderRadius: "50%", background: t.bg3, border: `1px solid ${t.border}`, cursor: "pointer", fontSize: 18, flexShrink: 0 }}>🗑</button>
          <div style={strip}>
            <div style={{ width: 10, height: 10, borderRadius: "50%", background: "#E8008A", animation: "pulse 1s ease-in-out infinite", flexShrink: 0 }} />
            <span style={{ color: t.accent, fontFamily: "'DM Mono',monospace", fontSize: 13, fontWeight: 700 }}>{fmt(voice.seconds)}</span>
            <span style={{ marginLeft: "auto", color: t.text3, fontFamily: "'DM Mono',monospace", fontSize: 11 }}>Enregistrement…</span>
          </div>
        </>
      )}

      {(showSend || locked) ? (
        <button key="send" onClick={locked ? lockedSend : send} aria-label="Envoyer" style={{ width: 44, height: 44, borderRadius: locked ? "50%" : 12, background: t.gradient, border: "none", color: "#fff", cursor: "pointer", fontSize: 18, flexShrink: 0, boxShadow: "0 4px 14px rgba(232,0,138,0.35)" }}>→</button>
      ) : (
        <button key="mic" aria-label="Maintenir pour enregistrer un vocal"
          onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onCancelGesture} onContextMenu={e => e.preventDefault()}
          style={{ width: 44, height: 44, borderRadius: "50%", background: holding ? t.accent : t.bg3, border: `1px solid ${holding ? t.accent : t.border}`, color: holding ? "#fff" : t.text2, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, touchAction: "none", WebkitTouchCallout: "none", transform: holding ? `translate(${drag.x}px, ${drag.y}px) scale(1.5)` : "none", transition: holding ? "none" : "transform 0.15s", zIndex: 6, boxShadow: holding ? "0 6px 22px rgba(232,0,138,0.55)" : "none" }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ pointerEvents: "none" }}>
            <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/><path d="M19 10v2a7 7 0 01-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/>
          </svg>
        </button>
      )}
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// DM CHAT
// ════════════════════════════════════════════════════════════════════════════════
const dmPreview = m => m.type==="voice" ? "🎙 Message vocal" : m.type==="image" ? "📷 Photo" : m.type==="video" ? "🎥 Vidéo" : m.type==="gif" ? "GIF" : m.text;

// Réduit les grosses photos (1600 px max) avant l'envoi
async function compressImage(file) {
  if (file.type === "image/gif" || file.size < 300 * 1024) return file;
  try {
    const bmp = await createImageBitmap(file);
    const scale = Math.min(1, 1600 / Math.max(bmp.width, bmp.height));
    const c = document.createElement("canvas");
    c.width = Math.round(bmp.width * scale); c.height = Math.round(bmp.height * scale);
    c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
    const blob = await new Promise(r => c.toBlob(r, "image/jpeg", 0.82));
    return blob ? new File([blob], "photo.jpg", { type: "image/jpeg" }) : file;
  } catch { return file; }
}

function MediaBubble({ msg, isMe, t, onOpen }) {
  const [url, setUrl] = useState(msg.media_url || null);
  const [err, setErr] = useState(false);
  useEffect(() => { if (!url && msg.media_path) api.mediaUrl(msg.media_path).then(setUrl).catch(() => setErr(true)); }, [msg.media_path]);
  const box = { maxWidth: 240, minWidth: 120, borderRadius: 16, overflow: "hidden", border: `1px solid ${isMe ? t.accent : t.border}`, background: t.bg3 };
  if (err) return <div style={{ ...box, padding: 12, fontSize: 12, color: t.text3, fontFamily: "'DM Mono',monospace" }}>⚠ Média indisponible</div>;
  if (!url) return <div style={{ ...box, height: 140, display: "flex", alignItems: "center", justifyContent: "center", color: t.text3, fontSize: 12, fontFamily: "'DM Mono',monospace" }}>Chargement…</div>;
  if (msg.type === "video") return <div style={box}><video src={url} controls playsInline preload="metadata" onError={() => setErr(true)} style={{ display: "block", width: "100%", maxHeight: 320 }} /></div>;
  return (
    <div style={{ ...box, cursor: "pointer" }} onClick={() => onOpen({ kind: msg.type, url })}>
      <img src={url} alt="" loading="lazy" onError={() => setErr(true)} style={{ display: "block", width: "100%", maxHeight: 320, objectFit: "cover" }} />
    </div>
  );
}

function MediaViewer({ item, onClose }) {
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.94)", zIndex: 320, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <img src={item.url} alt="" style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
      <button onClick={onClose} style={{ position: "absolute", top: "calc(14px + env(safe-area-inset-top, 0px))", right: 14, width: 38, height: 38, borderRadius: "50%", background: "rgba(255,255,255,0.15)", border: "none", color: "#fff", fontSize: 18, cursor: "pointer" }}>✕</button>
    </div>
  );
}

function MediaPreviewModal({ pending, sending, onSend, onCancel, t }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.92)", zIndex: 300, display: "flex", flexDirection: "column", padding: "calc(14px + env(safe-area-inset-top, 0px)) 14px calc(14px + env(safe-area-inset-bottom, 0px))" }}>
      <div style={{ flex: 1, minHeight: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
        {pending.kind === "video"
          ? <video src={pending.url} controls playsInline style={{ maxWidth: "100%", maxHeight: "100%", borderRadius: 12 }} />
          : <img src={pending.url} alt="" style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain", borderRadius: 12 }} />}
      </div>
      <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
        <Btn onClick={onCancel} t={t} disabled={sending} style={{ flex: 1 }}>Annuler</Btn>
        <Btn accent onClick={onSend} t={t} disabled={sending} style={{ flex: 2 }}>{sending ? "Envoi en cours…" : pending.kind === "video" ? "Envoyer la vidéo →" : "Envoyer la photo →"}</Btn>
      </div>
    </div>
  );
}

function GifPicker({ userId, onPick, onClose, t }) {
  const [q, setQ] = useState("");
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState(null);
  useEffect(() => {
    let alive = true; setLoading(true); setErr(null);
    const id = setTimeout(() => {
      searchGifs(q.trim(), userId)
        .then(r => { if (alive) { setItems(r); if (!r.length && !q.trim()) setErr("Aucun GIF reçu du fournisseur."); } })
        .catch(e => { console.error(e); if (alive) { setItems([]); setErr("Impossible de charger les GIFs."); } })
        .finally(() => alive && setLoading(false));
    }, q.trim() ? 350 : 0);
    return () => { alive = false; clearTimeout(id); };
  }, [q]);
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 310, display: "flex", alignItems: "flex-end" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 560, margin: "0 auto", height: "68%", background: t.bg2, borderTop: `1px solid ${t.border}`, borderRadius: "20px 20px 0 0", display: "flex", flexDirection: "column", padding: "14px 14px calc(10px + env(safe-area-inset-bottom, 0px))" }}>
        <div style={{ display: "flex", gap: 10, marginBottom: 10 }}>
          <input value={q} onChange={e => setQ(e.target.value)} placeholder="Rechercher un GIF…" autoFocus
            style={{ flex: 1, padding: "11px 14px", borderRadius: 12, background: t.input, border: `1px solid ${t.border}`, color: t.text, fontSize: 14, fontFamily: "'DM Mono',monospace", outline: "none" }} />
          <button onClick={onClose} style={{ width: 42, height: 42, borderRadius: "50%", background: t.bg3, border: `1px solid ${t.border}`, color: t.text3, cursor: "pointer", fontSize: 16 }}>✕</button>
        </div>
        <div style={{ flex: 1, overflowY: "auto" }}>
          {loading && <p style={{ textAlign: "center", color: t.text3, fontFamily: "'DM Mono',monospace", fontSize: 12, padding: 20 }}>Chargement…</p>}
          {!loading && err && <p style={{ textAlign: "center", color: t.text3, fontFamily: "'DM Mono',monospace", fontSize: 12, padding: 20 }}>{err}</p>}
          {!loading && !err && items.length === 0 && <p style={{ textAlign: "center", color: t.text3, fontFamily: "'DM Mono',monospace", fontSize: 12, padding: 20 }}>Aucun résultat.</p>}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
            {items.map(g => (
              <button key={g.id} onClick={() => onPick(g.url)} style={{ padding: 0, border: "none", background: t.bg3, borderRadius: 10, overflow: "hidden", cursor: "pointer", minHeight: 70 }}>
                <img src={g.thumb} alt={g.title} loading="lazy" style={{ display: "block", width: "100%", height: "auto" }} />
              </button>
            ))}
          </div>
        </div>
        <p style={{ margin: "8px 0 0", textAlign: "center", fontSize: 9, color: t.text3, fontFamily: "'DM Mono',monospace" }}>Propulsé par {gifProvider}</p>
      </div>
    </div>
  );
}

// ── RÉACTIONS ET ANNULATION D'ENVOI ─────────────────────────────
const QUICK_EMOJIS = ["❤️", "😂", "😮", "😢", "😡", "👍"];
const MORE_EMOJIS = ["🔥", "🎉", "🙏", "👏", "😍", "🤔", "😅", "🥳", "💯", "😎", "🤝", "👀", "💀", "🥹", "😭", "🤣", "🙌", "✨", "🍀", "🫶"];

function useReactions(scope, messages, meId) {
  const [map, setMap] = useState({});
  const ids = messages.map(m => m.id).filter(Boolean);
  const key = ids.join(",");
  const load = useCallback(() => {
    if (!ids.length) { setMap({}); return; }
    api.listReactions(scope, ids).then(rows => {
      const m = {}; rows.forEach(r => { (m[r.message_id] = m[r.message_id] || []).push(r); }); setMap(m);
    }).catch(() => {});
  }, [scope, key]);
  useEffect(() => {
    load();
    const id = setInterval(() => { if (document.visibilityState === "visible") load(); }, 6000);
    return () => clearInterval(id);
  }, [load]);
  const react = async (msg, emoji) => {
    const mine = (map[msg.id] || []).find(r => r.user_id === meId);
    const same = mine && mine.emoji === emoji;
    setMap(prev => {
      const list = (prev[msg.id] || []).filter(r => r.user_id !== meId);
      return { ...prev, [msg.id]: same ? list : [...list, { message_id: msg.id, user_id: meId, emoji }] };
    });
    try { await (same ? api.removeReaction(scope, msg.id, meId) : api.setReaction(scope, msg.id, meId, emoji)); }
    catch (e) { console.error(e); load(); }
  };
  return { map, react };
}

function MessageSheet({ msg, isMe, canModerate, myEmoji, onReact, onUnsend, onClose, t }) {
  const [more, setMore] = useState(false);
  const act = { display: "flex", alignItems: "center", gap: 12, width: "100%", padding: "14px 6px", background: "none", border: "none", borderTop: `1px solid ${t.border}`, color: t.text, fontFamily: "'DM Sans',sans-serif", fontSize: 15, cursor: "pointer", textAlign: "left" };
  const pick = (e) => { onReact(msg, e); onClose(); };
  const emojiBtn = (e) => (
    <button key={e} onClick={() => pick(e)} style={{ fontSize: 26, width: 46, height: 46, borderRadius: "50%", border: "none", cursor: "pointer", background: myEmoji === e ? t.accentBg : "transparent", outline: myEmoji === e ? `2px solid ${t.accent}` : "none" }}>{e}</button>
  );
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 350, display: "flex", alignItems: "flex-end", justifyContent: "center" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, background: t.bg2, borderRadius: "22px 22px 0 0", padding: "14px 16px calc(14px + env(safe-area-inset-bottom, 0px))", border: `1px solid ${t.border}` }}>
        <div style={{ width: 40, height: 4, borderRadius: 2, background: t.border2 || t.border, margin: "0 auto 12px" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: t.bg3, borderRadius: 30, padding: "4px 8px", marginBottom: 10 }}>
          {QUICK_EMOJIS.map(emojiBtn)}
          <button onClick={() => setMore(m => !m)} aria-label="Plus d'emojis" style={{ width: 40, height: 40, borderRadius: "50%", border: "none", cursor: "pointer", background: t.bg2, color: t.text2, fontSize: 20 }}>{more ? "–" : "＋"}</button>
        </div>
        {more && <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 2, marginBottom: 8 }}>{MORE_EMOJIS.map(emojiBtn)}</div>}
        {msg.text && <button style={act} onClick={() => { navigator.clipboard?.writeText(msg.text).catch(() => {}); onClose(); }}>📋 Copier</button>}
        {isMe && <button style={{ ...act, color: "#FF3B30" }} onClick={() => { if (window.confirm("Annuler l'envoi ? Ce message disparaîtra pour tout le monde.")) { onUnsend(msg); onClose(); } }}>↩️ Annuler l'envoi</button>}
        {!isMe && canModerate && <button style={{ ...act, color: "#FF3B30" }} onClick={() => { if (window.confirm("Supprimer ce message pour tout le monde ?")) { onUnsend(msg); onClose(); } }}>🗑 Supprimer le message</button>}
      </div>
    </div>
  );
}

function ReactionList({ reactions, myId, resolveUser, onRemove, onClose, t }) {
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 350, display: "flex", alignItems: "flex-end", justifyContent: "center" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, maxHeight: "60vh", overflowY: "auto", background: t.bg2, borderRadius: "22px 22px 0 0", padding: "16px 18px calc(16px + env(safe-area-inset-bottom, 0px))", border: `1px solid ${t.border}` }}>
        <h3 style={{ margin: "0 0 10px", fontFamily: "'Fraunces',serif", color: t.text, fontSize: 18 }}>Réactions</h3>
        {reactions.map(r => { const u = resolveUser(r.user_id); const mine = r.user_id === myId; return (
          <div key={r.user_id} onClick={mine ? () => { onRemove(); onClose(); } : undefined} style={{ display: "flex", alignItems: "center", gap: 12, padding: "8px 0", cursor: mine ? "pointer" : "default" }}>
            {u && <Avatar user={u} size={38} t={t} />}
            <div style={{ flex: 1, color: t.text, fontFamily: "'DM Sans',sans-serif", fontSize: 14 }}>{mine ? "Toi" : (u?.name || "Membre")}{mine && <div style={{ color: t.text3, fontSize: 11, fontFamily: "'DM Mono',monospace" }}>Touche pour retirer</div>}</div>
            <span style={{ fontSize: 24 }}>{r.emoji}</span>
          </div>); })}
      </div>
    </div>
  );
}

// Entoure une bulle de message : appui long / clic droit = menu, double toucher = ❤️, pastille de réactions
function MsgWrap({ msg, isMe, canModerate, reactions = [], myId, onReact, onUnsend, resolveUser, t, children }) {
  const [sheet, setSheet] = useState(false);
  const [list, setList] = useState(false);
  const [hover, setHover] = useState(false);
  const timer = useRef(null), lastTap = useRef(0), lastTouch = useRef(0), moved = useRef(false);
  const mine = reactions.find(r => r.user_id === myId);
  const start = () => { lastTouch.current = Date.now(); moved.current = false; clearTimeout(timer.current); timer.current = setTimeout(() => { if (!moved.current) { setSheet(true); try { navigator.vibrate?.(15); } catch {} } }, 450); };
  const cancel = () => clearTimeout(timer.current);
  const end = () => { cancel(); if (moved.current) return; const n = Date.now(); if (n - lastTap.current < 320) { onReact(msg, "❤️"); lastTap.current = 0; } else lastTap.current = n; };
  const counts = {}; reactions.forEach(r => { counts[r.emoji] = (counts[r.emoji] || 0) + 1; });
  const top = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 3);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: isMe ? "flex-end" : "flex-start", maxWidth: "100%" }}>
      <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)} style={{ display: "flex", alignItems: "center", gap: 6, flexDirection: isMe ? "row-reverse" : "row", maxWidth: "100%" }}>
        <div onTouchStart={start} onTouchMove={() => { moved.current = true; cancel(); }} onTouchEnd={end} onTouchCancel={cancel}
          onContextMenu={e => { e.preventDefault(); setSheet(true); }}
          onDoubleClick={() => { if (Date.now() - lastTouch.current > 800) onReact(msg, "❤️"); }}
          style={{ userSelect: "none", WebkitUserSelect: "none", WebkitTouchCallout: "none", minWidth: 0 }}>
          {children}
        </div>
        {hover && <button onClick={() => setSheet(true)} aria-label="Réagir" style={{ border: `1px solid ${t.border}`, background: t.bg2, color: t.text3, borderRadius: "50%", width: 28, height: 28, cursor: "pointer", fontSize: 15, flexShrink: 0 }}>☺</button>}
      </div>
      {top.length > 0 && (
        <button onClick={() => setList(true)} style={{ marginTop: -7, marginLeft: 8, marginRight: 8, display: "inline-flex", alignItems: "center", gap: 3, padding: "1px 7px", borderRadius: 12, cursor: "pointer", background: t.bg2, border: `1.5px solid ${mine ? t.accent : t.border}`, color: t.text2, fontSize: 13, fontFamily: "'DM Mono',monospace", lineHeight: 1.4, position: "relative" }}>
          {top.map(([e]) => <span key={e}>{e}</span>)}{reactions.length > 1 && <span style={{ fontSize: 11 }}>{reactions.length}</span>}
        </button>
      )}
      {sheet && <MessageSheet msg={msg} isMe={isMe} canModerate={canModerate} myEmoji={mine?.emoji} onReact={onReact} onUnsend={onUnsend} onClose={() => setSheet(false)} t={t} />}
      {list && <ReactionList reactions={reactions} myId={myId} resolveUser={resolveUser} onRemove={() => onReact(msg, mine?.emoji)} onClose={() => setList(false)} t={t} />}
    </div>
  );
}

function DMChat({currentUser, otherUser, messages, onSend, onVoiceSend, onSendMedia, onSendGif, onStatus, partnerStatus, onOpenProfile, onBack, onCall, group, onOpenInfo, statusName, onUnsend, t}) {
  const reactions = useReactions(group ? "group" : "dm", messages, currentUser.id);
  const resolveUser = id => id===currentUser.id ? currentUser : group ? group.memberUsers.find(u=>u.id===id) : otherUser;
  const bottomRef = useRef();
  const [pending, setPending] = useState(null);   // fichier choisi, en attente de confirmation
  const [sending, setSending] = useState(false);
  const [gifOpen, setGifOpen] = useState(false);
  const [viewer, setViewer] = useState(null);
  useEffect(()=>{ bottomRef.current?.scrollIntoView({behavior:"smooth"}); },[messages.length, messages[messages.length-1]?.id, partnerStatus]);

  const statusText = partnerStatus==="recording" ? "est en train d'enregistrer un vocal…" : partnerStatus==="typing" ? "est en train d'écrire…" : null;

  const pickFile = (file) => {
    const kind = file.type.startsWith("video/") ? "video" : file.type.startsWith("image/") ? "image" : null;
    if (!kind) { alert("Choisis une photo ou une vidéo."); return; }
    if (file.size > 30*1024*1024) { alert("Fichier trop lourd (30 Mo maximum)."); return; }
    setPending({ file, kind, url: URL.createObjectURL(file) });
  };
  const closePending = () => { if (pending) URL.revokeObjectURL(pending.url); setPending(null); };
  const confirmSend = async () => {
    if (!pending) return;
    setSending(true);
    try {
      const file = pending.kind==="image" ? await compressImage(pending.file) : pending.file;
      await onSendMedia(pending.kind, file);
      closePending();
    } finally { setSending(false); }
  };

  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%"}}>
      <div style={{padding:"16px 20px",borderBottom:`1px solid ${t.border}`,display:"flex",alignItems:"center",gap:12,background:t.bg2,flexShrink:0}}>
        <button onClick={onBack} style={{background:"none",border:"none",color:t.accent,cursor:"pointer",fontSize:18,display:"flex",alignItems:"center"}}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <div onClick={group?onOpenInfo:onOpenProfile} style={{cursor:"pointer",display:"flex"}}>{group ? <GroupAvatar group={group} size={40} t={t}/> : <Avatar user={otherUser} size={36} t={t} />}</div>
        <div onClick={group?onOpenInfo:onOpenProfile} style={{minWidth:0,cursor:"pointer"}}>
          <p style={{color:t.text,fontFamily:"'DM Sans',sans-serif",fontWeight:600,margin:0,fontSize:15}}>{group ? group.name : otherUser.name}</p>
          {group ? <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:11,margin:0}}>{group.memberUsers.length} membres · infos</p> : statusText
            ? <p style={{color:t.accent,fontFamily:"'DM Sans',sans-serif",fontStyle:"italic",fontSize:11,margin:0}}>{statusText}</p>
            : <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:11,margin:0}}>@{otherUser.pseudo}</p>}
        </div>
        {onCall && <div style={{marginLeft:"auto",display:"flex",gap:4}}>
          <button onClick={()=>onCall(false)} aria-label="Appel audio" style={{background:"none",border:"none",color:t.accent,cursor:"pointer",padding:8,display:"flex"}}>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.9v3a2 2 0 01-2.2 2 19.8 19.8 0 01-8.6-3.1 19.5 19.5 0 01-6-6A19.8 19.8 0 012.1 4.2 2 2 0 014.1 2h3a2 2 0 012 1.7c.1 1 .4 1.9.7 2.8a2 2 0 01-.5 2.1L8.1 9.9a16 16 0 006 6l1.3-1.3a2 2 0 012.1-.4c.9.3 1.8.6 2.8.7a2 2 0 011.7 2z"/></svg>
          </button>
          <button onClick={()=>onCall(true)} aria-label="Appel vidéo" style={{background:"none",border:"none",color:t.accent,cursor:"pointer",padding:8,display:"flex"}}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="23 7 16 12 23 17 23 7"/><rect x="1" y="5" width="15" height="14" rx="2"/></svg>
          </button>
        </div>}
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"16px 20px"}}>
        {messages.length===0&&<p style={{color:t.text3,textAlign:"center",fontFamily:"'DM Mono',monospace",fontSize:12,padding:"40px 0"}}>Commencez la conversation !</p>}
        {messages.map((m,i)=>{
          const isMe = m.senderId===currentUser.id;
          const isMedia = m.type==="image" || m.type==="video" || m.type==="gif";
          const sender = group ? (m.sender || group.memberUsers.find(u=>u.id===m.senderId)) : otherUser;
          return (
            <div key={m.id||i} style={{display:"flex",flexDirection:isMe?"row-reverse":"row",gap:8,marginBottom:14,alignItems:"flex-end"}}>
              {!isMe&&<div onClick={group?()=>onOpenProfile(sender):undefined} style={{cursor:group?"pointer":"default",display:"flex"}}><Avatar user={sender} size={28} t={t} /></div>}
              <div style={{maxWidth:"72%",display:"flex",flexDirection:"column",alignItems:isMe?"flex-end":"flex-start"}}>
                {group && !isMe && <span style={{fontSize:11,color:t.accent,fontFamily:"'DM Mono',monospace",margin:"0 0 3px 4px"}}>{sender?.pseudo}</span>}
                <MsgWrap msg={m} isMe={isMe} myId={currentUser.id} reactions={reactions.map[m.id]||[]} onReact={reactions.react} onUnsend={onUnsend} resolveUser={resolveUser} t={t}>
                {m.type==="voice" ? (
                  <VoiceMessageBubble msg={m} isMe={isMe} t={t} />
                ) : isMedia ? (
                  <MediaBubble msg={m} isMe={isMe} t={t} onOpen={setViewer} />
                ) : (
                  <div style={{background:isMe?t.accent:t.bg3,borderRadius:isMe?"16px 16px 4px 16px":"16px 16px 16px 4px",padding:"10px 14px",color:isMe?"#fff":t.text,fontSize:14,fontFamily:"'DM Sans',sans-serif",lineHeight:1.5,border:isMe?"none":`1px solid ${t.border}`}}>
                    {m.text}
                  </div>
                )}
                </MsgWrap>
                <p style={{fontSize:10,color:t.text3,fontFamily:"'DM Mono',monospace",margin:"3px 0 0"}}>{m.time}</p>
              </div>
            </div>
          );
        })}
        {statusText && <p style={{fontStyle:"italic",fontSize:11,color:t.text3,fontFamily:"'DM Sans',sans-serif",margin:"0 0 6px 36px"}}>{group ? statusName : otherUser.name.split(" ")[0]} {statusText}</p>}
        <div ref={bottomRef}/>
      </div>
      <ChatInputBar onSend={onSend} onVoiceSend={onVoiceSend} onStatus={onStatus} onPickFile={pickFile}
        onGif={gifsEnabled ? ()=>setGifOpen(true) : null} t={t} placeholder="Écrire un message…" padH={16} />
      {pending && <MediaPreviewModal pending={pending} sending={sending} onSend={confirmSend} onCancel={closePending} t={t} />}
      {gifOpen && <GifPicker userId={currentUser.id} t={t} onClose={()=>setGifOpen(false)} onPick={url=>{ setGifOpen(false); onSendGif(url); }} />}
      {viewer && <MediaViewer item={viewer} onClose={()=>setViewer(null)} />}
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// NOTIFICATIONS PANEL
// ════════════════════════════════════════════════════════════════════════════════
function NotifPanel({notifs, onMarkRead, onOpen, onClose, t}) {
  return (
    <div style={{position:"fixed",inset:0,zIndex:150}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{position:"absolute",top:"calc(56px + env(safe-area-inset-top, 0px))",right:16,width:320,maxWidth:"calc(100% - 32px)",maxHeight:400,background:t.bg2,border:`1px solid ${t.border}`,borderRadius:16,overflow:"hidden",boxShadow:"0 8px 32px rgba(0,0,0,0.3)"}}>
        <div style={{padding:"14px 16px",borderBottom:`1px solid ${t.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{fontFamily:"'DM Mono',monospace",fontSize:12,color:t.text,fontWeight:700}}>NOTIFICATIONS</span>
          <button onClick={onMarkRead} style={{background:"none",border:"none",color:t.accent,fontFamily:"'DM Mono',monospace",fontSize:11,cursor:"pointer"}}>Tout lu</button>
        </div>
        <div style={{overflowY:"auto",maxHeight:340}}>
          {notifs.length===0&&<p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:12,padding:"24px",textAlign:"center"}}>Aucune notification</p>}
          {notifs.map((n,i)=>(
            <div key={n.id||i} onClick={()=>onOpen&&onOpen(n)} style={{padding:"12px 16px",borderBottom:`1px solid ${t.border}`,background:n.read?"transparent":t.accentBg,cursor:"pointer",display:"flex",alignItems:"center",gap:10}}>
              <div style={{flex:1,minWidth:0}}>
                <p style={{color:t.text,fontFamily:"'DM Sans',sans-serif",fontSize:13,margin:"0 0 3px",lineHeight:1.4}}>{n.text}</p>
                <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:10,margin:0}}>{n.time}</p>
              </div>
              <span style={{color:t.text3,fontSize:18,flexShrink:0}}>›</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// ACTIVITY DETAIL
// ════════════════════════════════════════════════════════════════════════════════
function ActivityDetail({activity,currentUser,onBack,onAccept,onReject,onSendMessage,onSendVoice,onSendMedia,onSendGif,onUnsend,onJoin,onOpenProfile,onDelete,t}) {
  const bottomRef=useRef();
  const reactions=useReactions("activity",activity.messages||[],currentUser.id);
  const resolveUser=id=>id===currentUser.id?currentUser:[activity.creator,...(activity.accepted||[])].find(u=>u?.id===id);
  const [pending,setPending]=useState(null);
  const [sending,setSending]=useState(false);
  const [gifOpen,setGifOpen]=useState(false);
  const [viewer,setViewer]=useState(null);
  const pickFile=(file)=>{
    const kind=file.type.startsWith("video/")?"video":file.type.startsWith("image/")?"image":null;
    if(!kind){ alert("Choisis une photo ou une vidéo."); return; }
    if(file.size>30*1024*1024){ alert("Fichier trop lourd (30 Mo maximum)."); return; }
    setPending({file,kind,url:URL.createObjectURL(file)});
  };
  const closePending=()=>{ if(pending) URL.revokeObjectURL(pending.url); setPending(null); };
  const confirmSend=async()=>{
    if(!pending) return; setSending(true);
    try{ const f=pending.kind==="image"?await compressImage(pending.file):pending.file; await onSendMedia(activity.id,pending.kind,f); closePending(); } finally{ setSending(false); }
  };
  const isCreator=activity.creator?.id===currentUser.id;
  const isMember=activity.accepted?.some(u=>u.id===currentUser.id);
  const isPending=activity.pending?.some(u=>u.id===currentUser.id);
  useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:"smooth"})},[activity.messages?.length, activity.messages?.[activity.messages.length-1]?.id]);
  const formatDate=d=>new Date(d).toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long"});

  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%"}}>
      <div style={{padding:"20px 24px 0",overflowY:"auto",flex:isMember?undefined:1}}>
        <button onClick={onBack} style={{background:"none",border:"none",color:t.accent,cursor:"pointer",fontFamily:"'DM Mono',monospace",fontSize:13,padding:0,marginBottom:16}}>← Retour</button>
        <div style={{background:t.bg2,borderRadius:16,border:`1px solid ${t.border}`,padding:20,marginBottom:16}}>
          {activity.photo_url&&<img src={activity.photo_url} alt="" style={{width:"100%",maxHeight:240,objectFit:"cover",borderRadius:14,marginBottom:14,display:"block"}}/>}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}>
            <div>
              <span style={{fontSize:11,fontFamily:"'DM Mono',monospace",color:t.accent,letterSpacing:"0.1em"}}>{CAT_ICONS[activity.category]} {activity.category?.toUpperCase()}</span>
              <h2 style={{margin:"6px 0 10px",fontFamily:"'Fraunces',serif",fontSize:22,color:t.text,lineHeight:1.2}}>{activity.title}</h2>
            </div>
            {!isMember&&!isPending&&<Btn accent onClick={()=>onJoin(activity.id)} t={t}>S'inscrire</Btn>}
            {isPending&&<span style={{padding:"10px 16px",borderRadius:10,background:t.bg3,color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:12}}>⏳ En attente</span>}
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:14,fontSize:12,color:t.text3,fontFamily:"'DM Mono',monospace",marginBottom:12}}>
            <span>📅 {formatDate(activity.date)} à {activity.time}</span>
            <span>📍 {activity.location}</span>
            <span>👥 {activity.accepted?.length}/{activity.maxPeople}</span>
          </div>
          <p style={{margin:"0 0 12px",fontSize:14,color:t.text2,lineHeight:1.6,fontFamily:"'DM Sans',sans-serif"}}>{activity.description}</p>
          <div style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer"}} onClick={()=>onOpenProfile(activity.creator)}>
            <Avatar user={activity.creator} size={28} t={t} />
            <span style={{fontSize:12,color:t.text3,fontFamily:"'DM Mono',monospace"}}>Par <span style={{color:t.text}}>{activity.creator?.name}</span></span>{activity.creator?.is_premium&&<PremiumBadge size={14}/>}
          </div>
          {isCreator && onDelete && (
            <button onClick={()=>{ if (window.confirm(`Supprimer la sortie "${activity.title}" ?\n\nLes participants seront prévenus et le groupe de discussion sera supprimé. Cette action est définitive.`)) onDelete(activity.id); }}
              style={{marginTop:14,width:"100%",padding:"10px",borderRadius:10,background:"transparent",border:`1px solid ${t.accent}66`,color:t.accent,fontFamily:"'DM Mono',monospace",fontSize:12,cursor:"pointer"}}>
              🗑 Supprimer cette sortie
            </button>
          )}
        </div>
        {isCreator&&activity.pending?.length>0&&(
          <div style={{background:t.bg2,borderRadius:14,border:`1px solid ${t.accent}44`,padding:16,marginBottom:16}}>
            <p style={{margin:"0 0 12px",fontFamily:"'DM Mono',monospace",fontSize:11,color:t.accent}}>🔔 DEMANDES ({activity.pending.length})</p>
            {activity.pending.map(u=>(
              <div key={u.id} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 0",borderTop:`1px solid ${t.border}`}}>
                <div style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer"}} onClick={()=>onOpenProfile(u)}>
                  <Avatar user={u} size={32} t={t} />
                  <span style={{color:t.text,fontSize:14,fontFamily:"'DM Sans',sans-serif"}}>{u.name}</span>
                </div>
                <div style={{display:"flex",gap:8}}>
                  <button onClick={()=>onAccept(activity.id,u.id)} style={{padding:"6px 14px",borderRadius:8,background:t.greenBg,border:`1px solid ${t.green}44`,color:t.green,fontFamily:"'DM Mono',monospace",fontSize:12,cursor:"pointer"}}>✓</button>
                  <button onClick={()=>onReject(activity.id,u.id)} style={{padding:"6px 14px",borderRadius:8,background:t.accentBg,border:`1px solid ${t.accent}44`,color:t.accent,fontFamily:"'DM Mono',monospace",fontSize:12,cursor:"pointer"}}>✕</button>
                </div>
              </div>
            ))}
          </div>
        )}
        <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:16}}>
          {activity.accepted?.map(u=>(
            <div key={u.id} title={u.name} style={{cursor:"pointer"}} onClick={()=>onOpenProfile(u)}>
              <Avatar user={u} size={36} t={t} />
            </div>
          ))}
        </div>
      </div>
      {isMember?(
        <>
          <div style={{flex:1,overflowY:"auto",padding:"0 24px",minHeight:0}}>
            <div style={{borderTop:`1px solid ${t.border}`,paddingTop:16,marginBottom:8}}>
              <p style={{margin:"0 0 12px",fontFamily:"'DM Mono',monospace",fontSize:11,color:t.text3,letterSpacing:"0.1em"}}>💬 GROUPE</p>
              {activity.messages?.map(m=>{
                const isMe=m.sender?.id===currentUser.id;
                return (
                  <div key={m.id} style={{display:"flex",flexDirection:isMe?"row-reverse":"row",gap:10,marginBottom:16,alignItems:"flex-end"}}>
                    {!isMe&&<div onClick={()=>onOpenProfile(m.sender)} style={{cursor:"pointer"}}><Avatar user={m.sender} size={30} t={t}/></div>}
                    <div style={{maxWidth:"72%"}}>
                      {!isMe&&<p style={{margin:"0 0 3px",fontSize:11,color:t.text3,fontFamily:"'DM Mono',monospace"}}>{m.sender?.name}</p>}
                      <MsgWrap msg={m} isMe={isMe} canModerate={isCreator} myId={currentUser.id} reactions={reactions.map[m.id]||[]} onReact={reactions.react} onUnsend={(mm)=>onUnsend(activity.id,mm)} resolveUser={resolveUser} t={t}>
                      {m.type==="voice" ? (
                        <VoiceMessageBubble msg={m} isMe={isMe} t={t} />
                      ) : (m.type==="image"||m.type==="video"||m.type==="gif") ? (
                        <MediaBubble msg={m} isMe={isMe} t={t} onOpen={setViewer} />
                      ) : (
                        <div style={{background:isMe?t.accent:t.bg3,borderRadius:isMe?"16px 16px 4px 16px":"16px 16px 16px 4px",padding:"10px 14px",color:isMe?"#fff":t.text,fontSize:14,fontFamily:"'DM Sans',sans-serif",lineHeight:1.5,border:isMe?"none":`1px solid ${t.border}`}}>{m.text}</div>
                      )}
                      </MsgWrap>
                      <p style={{margin:"3px 0 0",fontSize:10,color:t.text3,fontFamily:"'DM Mono',monospace",textAlign:isMe?"right":"left"}}>{m.time}</p>
                    </div>
                  </div>
                );
              })}
              <div ref={bottomRef}/>
            </div>
          </div>
          <ChatInputBar
            onSend={(text)=>onSendMessage(activity.id,text)}
            onVoiceSend={(url,dur,blob)=>onSendVoice(activity.id,blob,dur)}
            t={t}
            placeholder="Écrire au groupe…"
            padH={24}
            onPickFile={pickFile}
            onGif={gifsEnabled ? ()=>setGifOpen(true) : null}
          />
          {pending && <MediaPreviewModal pending={pending} sending={sending} onSend={confirmSend} onCancel={closePending} t={t} />}
          {gifOpen && <GifPicker userId={currentUser.id} t={t} onClose={()=>setGifOpen(false)} onPick={url=>{ setGifOpen(false); onSendGif(activity.id,url); }} />}
          {viewer && <MediaViewer item={viewer} onClose={()=>setViewer(null)} />}
        </>
      ):(
        <div style={{padding:"12px 24px 28px",textAlign:"center"}}>
          <div style={{background:t.bg2,border:`1px dashed ${t.border}`,borderRadius:14,padding:20}}>
            <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:13,margin:0}}>{isPending?"⏳ Votre demande est en cours d'examen.":"🔒 Inscrivez-vous pour rejoindre le groupe."}</p>
          </div>
        </div>
      )}
    </div>
  );
}

