    const stream = await getMedia(gc.video);
    if (!stream) { cleanup(); return; }
    const r = R.current; r.local = stream; setLocal(stream);
    setGcall({ ...gc, status: "connecting" });
    gSend(gc, { type: "ghello", reply: false });
